CREATE TABLE gold.monthly_session_metrics (`month_bucket` DateTime('UTC') CODEC(ZSTD(1)), `platform` LowCardinality(String) CODEC(ZSTD(1)), `video_resolution` LowCardinality(String) CODEC(ZSTD(1)), `country` LowCardinality(String) CODEC(ZSTD(1)), `audio_languages` AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)), `subtitle_languages` AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)), `category` LowCardinality(String) CODEC(ZSTD(1)), `show_name` LowCardinality(String) CODEC(ZSTD(1)), `title` LowCardinality(String) CODEC(ZSTD(1)), `active_users_state` AggregateFunction(uniqExact, FixedString(64)) CODEC(ZSTD(1)), `active_session_state` AggregateFunction(uniqExact, FixedString(64)) CODEC(ZSTD(1))) ENGINE = SharedAggregatingMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(month_bucket) ORDER BY (month_bucket, platform, video_resolution, country, category, show_name, title) SETTINGS index_granularity = 8192